questionvariables.text:
Laenge:  rand_with_step(1.5,2.5,0.5); /* m */
Dm:  rand_with_step(80,120,10)/100;   /* cm */
alpha: rand_with_step(10,40,10);      /* ° */
rho: rand_with_step(1,1.3,0.1)*1000;  /* kg/dm³ */
ge: 10;                               /* m/s² */

FG: pi/4*(Dm/100)^2*Laenge*1000*rho*ge;  /* N */
FA: FG*cos(alpha*pi/180);
FB: FG*sin(alpha*pi/180);

texput(deg, "\\mathrm{{}^{o}}");

/* Kurzkennzeichnung der Variante fuer die Fragenuebersicht/questionnote:
   randomisierte Vorgaben plus die daraus folgenden Loesungen. */
ta1: sconcat("alpha=",alpha,"; D=",Dm,"m; l=",Laenge,"m; rho=",rho,"kg/m^3; ",
             "G=",dispsf(FG,3),"N; A=",dispsf(FA,3),"N; B=",dispsf(FB,3),"N");

/* --- meclib-Skizze der Krangabel mit Kontaktpunkten --- */
r: 2;                 /* Rollenradius in Gittereinheiten -- */

uAx: cos(alpha*pi/180); uAy: sin(alpha*pi/180);
uBx: -sin(alpha*pi/180); uBy: cos(alpha*pi/180);
V:  [0,0];
C:  [r*(uAx+uBx), r*(uAy+uBy)];
PA: [r*uAx, r*uAy];
PB: [r*uBx, r*uBy];
armlen: 2*r;
th: 0.3*r;
PAo: [armlen*uAx - th*uBx, armlen*uAy - th*uBy];
PAi: [armlen*uAx, armlen*uAy];
PBi: [armlen*uBx, armlen*uBy];
PBo: [armlen*uBx - th*uAx, armlen*uBy - th*uAy];
Vo:  [-th*(uAx+uBx), -th*(uAy+uBy)];

initdata: [
  ["grid", "", "", PBo[1]-1.0, PAo[1]+1.0, Vo[2]-1.0, 3.5*r, 40],
  ["polygon", "Die Gabel", PAo, PAi, V, PBi, PBo, Vo, "show"],
  ["circle", "", C, r, 0, "SHOW"],
  ["line", "black", [C[1]-(r+0.2), C[1]+(r+0.2)], [C[2], C[2]], "-."],
  ["line", "black", [C[1], C[1]], [C[2]-(r+0.2), C[2]+(r+0.2)], "-."],
  ["dim", "D", [C[1]-r, C[2]], [C[1]+r, C[2]], r+0.5],
  ["point", "A", PA],
  ["point", "B", PB],
  ["point", "S", C],
  ["force", "G", C, [C[1], C[2]-1.5], 10, "locked"],
  ["angle", "\\alpha", PBi, PBi+[0,2], 0.9*r, alpha],
  ["contact", "", PA, [uBx, uBy], "Die Gabel", 3],
  ["contact", "", PB, [uAx, uAy], "Die Gabel", 3],
  ["forceGen", "F", [PAo[1]-1, 3*r]],
  ["dir", "1", V, 0, 10, 1.5*r, "active"],
  ["dir", "2", V, 90, 10, 1.5*r, "active"]
];
init: stackjson_stringify(initdata);

i_A: 12; i_B: 13;
i_circle: 3; i_gabel: 2;
i_dir1: 15; i_dir2: 16;
sys: [i_circle]; env: [i_gabel];

/* --- Referenzlösung für die interaktiven Inputs "objects"/"names" --- */
refdata: [
  ["grid", "", "", PBo[1]-1.0, PAo[1]+1.0, Vo[2]-1.0, 3.5*r, 40],
  ["polygon", "Die Gabel", PAo, PAi, V, PBi, PBo, Vo, "hide"],
  ["circle", "", C, r, 0, "SHOW"],
  ["line", "black", [C[1]-(r+0.2), C[1]+(r+0.2)], [C[2], C[2]], "-."],
  ["line", "black", [C[1], C[1]], [C[2]-(r+0.2), C[2]+(r+0.2)], "-."],
  ["dim", "D", [C[1]-r, C[2]], [C[1]+r, C[2]], r+0.5],
  ["point", "A", PA],
  ["point", "B", PB],
  ["point", "S", C],
  ["force", "G", C, [C[1], C[2]-1.5], 10, "locked"],
  ["angle", "\\alpha", PBi, PBi+[0,2], 0.9*r, alpha],
  ["contact", "", PA, [uBx, uBy], "Die Gabel", 3 ],
  ["contact", "", PB, [uAx, uAy], "Die Gabel", 3 ],
  ["forceGen", "F_1", [PAo[1]-1, 3*r]],
  /* dir1/dir2 bleiben an derselben Position wie in initdata (Index 15/16, siehe i_dir1/i_dir2
     unten), die geloesten Kraefte kommen wie bei einem echten Freischnitt erst danach dazu.
     Winkel auf die guenstige ("gedrehte") Richtung senkrecht zu B bzw. A gelegt. */
  ["dir", "1", V, 90+alpha, 10, 1.5*r, "active"],
  ["dir", "2", V, alpha, 10, 1.5*r, "active"],
  ["force", "A", PA-[uBx,uBy], PA, 10, "active"],
  ["force", "B", PB-[uAx,uAy], PB, 10, "active"]
];
ref: stackjson_stringify(refdata);

/* --- Static reference equations of equilibrium for question preview */
GG1_tans: A-cos(alpha*deg)*G;
GG2_tans: B-sin(alpha*deg)*G;

/* Rein fuer die Anzeige im allgemeinen Feedback: dieselbe (fuer jedes alpha
   allgemeingueltige) Loesung, aber mit "deg" nur zur Gradnotation in der Ausgabe
   (z.B. "cos(20 deg)" -> "cos(20°)") - deg wird dabei nie ausgewertet, nur getippt,
   und diese Variablen werden nirgends zur Bewertung herangezogen. */
GG1_disp: A - G*cos(alpha*deg);
GG2_disp: B - G*sin(alpha*deg);

/* --- (non-interactive) sketch for general feedback ---*/
gfbdata: [
  ["grid", "", "", PBo[1]-1.0, PAo[1]+1.0, Vo[2]-1.0, 3.5*r, 40],
  ["polygon", "Die Gabel", PAo, PAi, V, PBi, PBo, Vo, "HIDE"],
  ["circle", "", C, r, 0, "SHOW"],
  ["line", "black", [C[1]-(r+0.2), C[1]+(r+0.2)], [C[2], C[2]], "-."],
  ["line", "black", [C[1], C[1]], [C[2]-(r+0.2), C[2]+(r+0.2)], "-."],
  ["dim", "D", [C[1]-r, C[2]], [C[1]+r, C[2]], r+0.5],
  ["point", "A", PA],
  ["point", "B", PB],
  ["point", "S", C],
  ["force", "G", C, [C[1], C[2]-1.5], 10, "locked"],
  ["angle", "\\alpha", PBi, PBi+[0,2], 0.9*r, alpha],
  ["contact", "", PA, [uBx, uBy], "Die Gabel", 3 ],
  ["contact", "", PB, [uAx, uAy], "Die Gabel", 3 ],
  ["dir", "1", V, 90+alpha, 10, 1.5*r],
  ["dir", "2", V, alpha, 10, 1.5*r],
  ["force", "A", PA-[uBx,uBy], PA, 10, "locked"],
  ["force", "B", PB-[uAx,uAy], PB, 10, "locked"]
];
gfb: stackjson_stringify(gfbdata);


stack_include("https://raw.githubusercontent.com/mkraska/meclib/dev2026/Maxima/fb_value.mac" );
stack_include("https://raw.githubusercontent.com/mkraska/meclib/dev2026/Maxima/fb_fbd.mac" );

feedbackvariables.text:
obj: stackjson_parse(objects);
[textA, okA]: fb_contact(obj, names, 12, "Kontakt A: ");
[textB, okB]: fb_contact(obj, names, 13, "Kontakt B: ");
[textSys, okSys]: fb_system(names, sys, env, " Die Rolle gehört zum System, die Gabel gehört zur Umgebung." );
[textR, okR]: fb_reactions(obj, 2, 0);

obj: stackjson_parse(objects);
d1: direction(obj[i_dir1]);
GG1: sum_dir(obj, names, d1);
[textGG1, okGG1]: fb_coeffs(deg2rad(S_GG1), GG1, 0.05, "");

obj: stackjson_parse(objects);
d2: direction(obj[i_dir2]);
GG2: sum_dir(obj, names, d2);
[textGG2, okGG2]: fb_coeffs(deg2rad(S_GG2), GG2, 0.05, "");
